/*
 * prog51_union_find.c
 * Re‑implementation of the original program (originally compiled from a
 * C source that performed a simple disjoint‑set / union‑find on ten
 * elements).  The binary is heavily obfuscated, but its observable
 * behaviour can be described as follows:
 *
 *   * The program works on a fixed universe of elements {0,…,9}.
 *   * It expects a sequence of commands on the command line, each
 *     command being a single‑character token followed by the required
 *     numeric arguments:
 *
 *         U a b   – union the sets containing a and b
 *         F a     – find the representative of a
 *         C a b   – check whether a and b are in the same set
 *
 *     Tokens are case‑sensitive and must be exactly one character long.
 *     All numbers are interpreted with `strtol(...,10)`.  If a number is
 *     outside the range 0‑9, or if a command does not have enough
 *     arguments, the program prints "INVALID".
 *
 *   * For a successful UNION it prints:
 *
 *         UNION %ld %ld\n
 *
 *   * For a successful FIND it prints:
 *
 *         FIND %ld=%d\n          // %ld is the element, %d is its root
 *
 *   * For a successful CONNECT (C) it prints either "YES" or "NO".
 *
 *   * If the program is invoked without any command (i.e. argc < 2)
 *     it prints "NOOP" and exits.
 *
 *   * Any unrecognised token also results in "INVALID".
 *
 * The implementation below follows the exact observable output of the
 * original binary while keeping the code clear and idiomatic.
 */

#include <stdio.h>
#include <stdlib.h>

#define N 10                     /* fixed number of elements */

/* Disjoint‑set data structure with union by rank and path compression */
static int parent[N];
static int rank_[N];

/* Initialise each element to be its own parent and rank 0 */
static void dsu_init(void)
{
    for (int i = 0; i < N; ++i) {
        parent[i] = i;
        rank_[i] = 0;
    }
}

/* Find with path compression */
static int dsu_find(int x)
{
    if (parent[x] != x)
        parent[x] = dsu_find(parent[x]);
    return parent[x];
}

/* Union by rank */
static void dsu_union(int x, int y)
{
    int rx = dsu_find(x);
    int ry = dsu_find(y);
    if (rx == ry)
        return;

    if (rank_[rx] < rank_[ry]) {
        parent[rx] = ry;
    } else {
        parent[ry] = rx;
        if (rank_[rx] == rank_[ry])
            ++rank_[rx];
    }
}

/* Helper: check that a value is a valid element index */
static int valid_index(long v)
{
    return v >= 0 && v < N;
}

int main(int argc, char **argv)
{
    /* No commands supplied → NOOP */
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    dsu_init();

    int i = 1;                     /* current token index */
    while (i < argc) {
        char *cmd = argv[i];

        /* Commands must be a single character */
        if (cmd[0] == '\0' || cmd[1] != '\0') {
            puts("INVALID");
            ++i;
            continue;
        }

        if (cmd[0] == 'U') {               /* UNION command */
            if (i + 2 >= argc) {           /* not enough arguments */
                puts("INVALID");
                break;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            long b = strtol(argv[i + 2], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) {
                puts("INVALID");
            } else {
                dsu_union((int)a, (int)b);
                printf("UNION %ld %ld\n", a, b);
            }
            i += 3;
        }
        else if (cmd[0] == 'F') {          /* FIND command */
            if (i + 1 >= argc) {
                puts("INVALID");
                break;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            if (!valid_index(a)) {
                puts("INVALID");
            } else {
                int root = dsu_find((int)a);
                printf("FIND %ld=%d\n", a, root);
            }
            i += 2;
        }
        else if (cmd[0] == 'C') {          /* CONNECT / SAME‑SET command */
            if (i + 2 >= argc) {
                puts("INVALID");
                break;
            }
            long a = strtol(argv[i + 1], NULL, 10);
            long b = strtol(argv[i + 2], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) {
                puts("INVALID");
            } else {
                int ra = dsu_find((int)a);
                int rb = dsu_find((int)b);
                puts(ra == rb ? "YES" : "NO");
            }
            i += 3;
        }
        else {                              /* unknown token */
            puts("INVALID");
            ++i;
        }
    }

    return 0;
}
